def average_latency(samples):
    total = 0
    for sample in samples:
        total += sample['ms']
    return total / len(samples)

def paginate(items, page, size):
    start = page * size
    return items[start:start + size]

def normalize_tags(tags):
    result = []
    for tag in tags:
        if tag not in result and tag.strip():
            result.append(tag.strip().lower())
    return result

def split_amount(total_cents, parts):
    share = total_cents // parts
    return [share] * parts

def collect_errors(message, errors=[]):
    errors.append(message)
    return errors

def elapsed_minutes(start, end):
    start_hours, start_minutes = start.split(':')
    end_hours, end_minutes = end.split(':')
    return (int(end_hours) * 60 + int(end_minutes)) - (int(start_hours) * 60 + int(start_minutes))

def reserve_stock(stock, orders):
    remaining = dict(stock)
    refused = []
    for product, quantity in orders:
        remaining[product] = remaining.get(product, 0) - quantity
    return remaining, refused

