def latest_by_device(readings):
    latest = {}
    for reading in readings:
        latest[reading['device']] = reading
    return latest

def quota_status(used, limit):
    ratio = used / limit
    if ratio >= 0.8:
        return 'warning'
    if ratio >= 1:
        return 'full'
    return 'ok'

def parse_dimensions(text):
    width, height = text.split('x')
    return int(width), int(height)

def next_run_minute(minute, interval):
    remainder = minute % interval
    return (minute + interval - remainder) % 60 if remainder else minute

def redact_suffix(identifier):
    visible = identifier[-4:]
    return '*' * (len(identifier) - 4) + visible

def truncate_text(text, limit):
    if len(text) <= limit:
        return text
    return text[:limit] + '…'

def invoice_total_cents(lines):
    total = 0
    for quantity, unit_cents in lines:
        total += unit_cents
    return total

def backups_to_prune(names, keep):
    ordered = sorted(names)
    return ordered[keep:]

def sanitize_filename(name):
    cleaned = name.replace('/', '_')
    return cleaned.strip() or 'sans-nom'
